import sys
from collections import defaultdict, deque

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def has_true_closed_chain(needles):
    parent = {}
    rank = {}

    for x1, y1, z1, x2, y2, z2 in needles:
        for x, y, z in [(x1, y1, z1), (x2, y2, z2)]:
            if (x, y, z) not in parent:
                parent[(x, y, z)] = (x, y, z)
                rank[(x, y, z)] = 0

    for x1, y1, z1, x2, y2, z2 in needles:
        if find(parent, (x1, y1, z1)) == find(parent, (x2, y2, z2)):
            return True
        union(parent, rank, (x1, y1, z1), (x2, y2, z2))

    return False

def has_floor_closed_chain(needles):
    floor_needles = defaultdict(list)

    for x1, y1, z1, x2, y2, z2 in needles:
        floor_needles[(x1, y1)].append((x2, y2))
        floor_needles[(x2, y2)].append((x1, y1))

    visited = set()

