        if node in visited:
            if len(path) >= 3 and path[0] == node:
                return True
            return False
        visited.add(node)
        path.append(node)
        for neighbor in floor_needles[node]:
            if neighbor != prev_node:
                if dfs(neighbor, node, path):
                    return True
        path.pop()
        return False

    for start in floor_needles:
        if start not in visited:
            if dfs(start, None, []):
                return True

    return False

